//! All SQL for notes. Queries are checked against the real schema at compile
//! time by `sqlx::query!`/`query_as!`. Column types (UUID, TIMESTAMP, enums)
//! come from server/sqlx.toml, generated by `just check`.

use sqlx::{SqliteExecutor, SqlitePool};
use uuid::Uuid;

use super::types::NoteStats;
use crate::db::{Note, NotePriority};

pub async fn list(
    db: &SqlitePool,
    search: Option<&str>,
    done: Option<bool>,
    limit: i64,
) -> sqlx::Result<Vec<Note>> {
    // Optional filters: a NULL parameter disables its condition. LIKE is
    // case-insensitive for ASCII letters.
    sqlx::query_as!(
        Note,
        r#"
        SELECT id, title, body, done, priority, word_count, created_at, updated_at
        FROM notes
        WHERE ($1 IS NULL OR title LIKE '%' || $1 || '%' OR body LIKE '%' || $1 || '%')
          AND ($2 IS NULL OR done = $2)
        -- Same expressions as the notes_list index, so no sort is needed.
        ORDER BY CASE priority WHEN 'high' THEN 2 WHEN 'normal' THEN 1 ELSE 0 END DESC,
                 created_at DESC, id DESC
        LIMIT $3
        "#,
        search,
        done,
        limit,
    )
    .fetch_all(db)
    .await
}

pub async fn get<'e>(db: impl SqliteExecutor<'e>, id: Uuid) -> sqlx::Result<Option<Note>> {
    sqlx::query_as!(
        Note,
        r#"
        SELECT id, title, body, done, priority, word_count, created_at, updated_at
        FROM notes WHERE id = $1
        "#,
        id
    )
    .fetch_optional(db)
    .await
}

pub async fn insert<'e>(
    db: impl SqliteExecutor<'e>,
    title: &str,
    body: &str,
    priority: NotePriority,
) -> sqlx::Result<Note> {
    // UUIDv7: random, but sorted by creation time (good for indexes).
    let id = Uuid::now_v7();
    sqlx::query_as!(
        Note,
        r#"
        INSERT INTO notes (id, title, body, priority) VALUES ($1, $2, $3, $4)
        RETURNING id, title, body, done, priority, word_count, created_at, updated_at
        "#,
        id,
        title,
        body,
        priority,
    )
    .fetch_one(db)
    .await
}

/// Partial update: `None` leaves a column unchanged. The word count is reset
/// when the body changes, and recomputed by the analyze job.
pub async fn update<'e>(
    db: impl SqliteExecutor<'e>,
    id: Uuid,
    title: Option<&str>,
    body: Option<&str>,
    done: Option<bool>,
    priority: Option<NotePriority>,
) -> sqlx::Result<Option<Note>> {
    sqlx::query_as!(
        Note,
        r#"
        UPDATE notes SET
            title      = COALESCE($2, title),
            body       = COALESCE($3, body),
            done       = COALESCE($4, done),
            priority   = COALESCE($5, priority),
            word_count = CASE WHEN $3 IS NULL THEN word_count ELSE NULL END,
            updated_at = strftime('%Y-%m-%dT%H:%M:%f+00:00')
        WHERE id = $1
        RETURNING id, title, body, done, priority, word_count, created_at, updated_at
        "#,
        id,
        title,
        body,
        done,
        priority,
    )
    .fetch_optional(db)
    .await
}

pub async fn delete(db: &SqlitePool, id: Uuid) -> sqlx::Result<bool> {
    let res = sqlx::query!("DELETE FROM notes WHERE id = $1", id)
        .execute(db)
        .await?;
    Ok(res.rows_affected() > 0)
}

pub async fn set_word_count(db: &SqlitePool, id: Uuid, words: i64) -> sqlx::Result<()> {
    sqlx::query!("UPDATE notes SET word_count = $2 WHERE id = $1", id, words)
        .execute(db)
        .await?;
    Ok(())
}

pub async fn stats(db: &SqlitePool) -> sqlx::Result<NoteStats> {
    // Computed columns have no table type: annotate them ("name: Type", and
    // "name!" for never null).
    let row = sqlx::query!(
        r#"
        SELECT
            count(*)                                      AS "total!: i64",
            count(*) FILTER (WHERE done)                  AS "done!: i64",
            COALESCE(sum(word_count), 0)                  AS "words!: i64",
            (SELECT max(day) FROM note_digests)           AS "last_digest_day: chrono::NaiveDate"
        FROM notes
        "#
    )
    .fetch_one(db)
    .await?;
    Ok(NoteStats {
        total: row.total,
        done: row.done,
        words: row.words,
        last_digest_day: row.last_digest_day,
    })
}

/// Upsert so the digest job is idempotent: re-running it rewrites the row.
pub async fn write_digest(db: &SqlitePool, day: chrono::NaiveDate) -> sqlx::Result<()> {
    sqlx::query!(
        r#"
        INSERT INTO note_digests (day, total, done, words)
        SELECT $1, count(*), count(*) FILTER (WHERE done), COALESCE(sum(word_count), 0)
        FROM notes WHERE created_at < date($1, '+1 day')
        ON CONFLICT (day) DO UPDATE
            SET total = excluded.total, done = excluded.done, words = excluded.words,
                created_at = strftime('%Y-%m-%dT%H:%M:%f+00:00')
        "#,
        day
    )
    .execute(db)
    .await?;
    Ok(())
}
